def get_next(n):
    total_sum = 0
    while n > 0:
        n, digit = divmod(n, 10)
        total_sum += digit ** 2
    return total_sum

def is_happy(n):
    s = set()
    while n != 1 and not(n in s):
        s.add(n)
        n = get_next(n)
    return n == 1

